package main

import (
	"fmt"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

// 中间件就是一个普通函数，参数是 *gin.Context，没有返回值
func before(c *gin.Context) {
	fmt.Println("中间件：请求进来", c.Request.URL.Path)
	c.Next() // 把控制权交给后面的 handler
}

func main() {
	gin.SetMode(gin.ReleaseMode)

	r := gin.New()
	r.Use(before)
	r.GET("/hello", func(c *gin.Context) {
		fmt.Println("handler：处理 /hello")
		c.String(200, "hello")
	})

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/hello", nil))

	fmt.Println("响应:", w.Code, w.Body.String())
}

package main

import (
	"fmt"

	"github.com/gin-gonic/gin"
)

func auth(c *gin.Context) {
	fmt.Println("鉴权中间件")
	c.Next()
}

func main() {
	gin.SetMode(gin.ReleaseMode)

	// HandlerFunc 就是 func(*gin.Context) 的具名类型
	var mw gin.HandlerFunc = auth
	fmt.Printf("类型: %T\n", mw)

	r := gin.New()
	r.Use(mw)
	r.Use(func(c *gin.Context) { // 也可以直接传函数字面量
		fmt.Println("匿名中间件")
		c.Next()
	})
	fmt.Println("已注册中间件数:", len(r.Handlers))
}

package main

import (
	"fmt"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func count(c *gin.Context) {
	c.Next()
	fmt.Println("经过中间件:", c.Request.URL.Path)
}

func main() {
	gin.SetMode(gin.ReleaseMode)

	r := gin.New()
	r.Use(count) // 必须在注册路由之前
	r.GET("/a", func(c *gin.Context) { c.String(200, "a") })
	r.GET("/b", func(c *gin.Context) { c.String(200, "b") })

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/b", nil))
	fmt.Println("响应:", w.Code, w.Body.String())
}

