	r.GET("/secret", func(c *gin.Context) {
		fmt.Println("不该执行到这里")
		c.String(200, "secret")
	})

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/secret", nil))
	fmt.Println("响应:", w.Code, w.Body.String())
