package main

import (
	"fmt"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func auth(c *gin.Context) {
	token := c.GetHeader("Authorization")
	if token != "Bearer secret" {
		c.AbortWithStatusJSON(401, gin.H{"error": "未认证"})
		return
	}
	c.Set("user", "张三")
	c.Next()
}

func main() {
	gin.SetMode(gin.ReleaseMode)

	r := gin.New()
	r.Use(auth)
	r.GET("/me", func(c *gin.Context) {
		user, _ := c.Get("user")
		c.JSON(200, gin.H{"user": user})
	})

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/me", nil))
	fmt.Println("没带 token:", w.Code, w.Body.String())

	w2 := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/me", nil)
	req.Header.Set("Authorization", "Bearer secret")
	r.ServeHTTP(w2, req)
	fmt.Println("带了 token:", w2.Code, w2.Body.String())
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	// 账号密码写死在代码里，只适合内部工具
	r.Use(gin.BasicAuth(gin.Accounts{"admin": "123456"}))
	r.GET("/admin", func(c *gin.Context) {
		user, _ := c.Get(gin.AuthUserKey)
		c.JSON(http.StatusOK, gin.H{"user": user})
	})

	// 没带凭据：401 + WWW-Authenticate
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/admin", nil))
	fmt.Println(w.Code, w.Header().Get("WWW-Authenticate"))

	// 带上正确凭据
	req := httptest.NewRequest(http.MethodGet, "/admin", nil)
	req.SetBasicAuth("admin", "123456")
	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, req)
	fmt.Println(w2.Code, w2.Body.String())
}

package main

import (
	"fmt"
	"net/http/httptest"
	"time"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	done := make(chan string, 1)

	r.GET("/async/:id", func(c *gin.Context) {
		cc := c.Copy() // 交给 goroutine 前先复制
		go func() {
			time.Sleep(10 * time.Millisecond)
			done <- cc.Param("id") // 复制出来的 Params 仍然可用
		}()
		c.String(200, "accepted")
	})

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/async/42", nil))
	fmt.Println(w.Code, w.Body.String())
	fmt.Println("goroutine 拿到:", <-done)
}

