package main

import (
	"fmt"
	"net/http/httptest"
	"time"

	"github.com/gin-gonic/gin"
)

// 全局中间件：记日志 + 计时
func logger(c *gin.Context) {
	start := time.Now()
	path := c.Request.URL.Path
	c.Next()
	fmt.Printf("[log] %s %s %d %v\n", c.Request.Method, path, c.Writer.Status(), time.Since(start))
}

// 组中间件：认证
func auth(c *gin.Context) {
	if c.GetHeader("Authorization") != "Bearer secret" {
		c.AbortWithStatusJSON(401, gin.H{"error": "未认证"})
		return
	}
	c.Set("user", "张三")
	c.Next()
}

func main() {
	gin.SetMode(gin.ReleaseMode)

	r := gin.New()
	r.Use(logger)

	api := r.Group("/api")
	api.Use(auth)
	api.GET("/me", func(c *gin.Context) {
		user, _ := c.Get("user")
		c.JSON(200, gin.H{"user": user})
	})

	r.GET("/ping", func(c *gin.Context) {
		c.String(200, "pong")
	})

	// 没带 token：被认证中间件拦下
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/api/me", nil))
	fmt.Println("无 token:", w.Code, w.Body.String())

	// 带上 token：handler 拿到中间件传来的用户
	w2 := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/api/me", nil)
	req.Header.Set("Authorization", "Bearer secret")
	r.ServeHTTP(w2, req)
	fmt.Println("有 token:", w2.Code, w2.Body.String())
}
